<script>
"use strict";

// 16-key keypad: CHIP-8 key -> keyboard key
const KEYMAP = {
  '1':'1','2':'2','3':'3','C':'4',
  '4':'q','5':'w','6':'e','D':'r',
  '7':'a','8':'s','9':'d','E':'f',
